  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_01347",
          "explanation": "The doctor used targeted, non-shaming language to distinguish cervical screening from endometrial cancer risk.",
          "quote": "宫颈 HPV 和 TCT 筛查是查宫颈癌的"
        },
        {
          "event_id": "lite_evt_00087",
          "explanation": "The family performed a teach-back showing the misconception was corrected and integrated.",
          "quote": "宫颈那张阴性不能说明子宫里面没事"
        }
      ],
      "completion": "complete",
      "explanation": "The misunderstanding was triggered from the opening and repeatedly resurfaced. The doctor corrected it in accessible language and the family restated the key point, reducing reliance on cervical screening as a reason to delay endometrial-pathology care.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00919",
          "explanation": "The doctor distinguished non-atypical, high-risk atypical hyperplasia, possible early cancer, and evidence needed for definitive diagnosis.",
          "quote": "不是基于癌的诊断已经成立的"
        },
        {
          "event_id": "lite_evt_00314",
          "explanation": "The doctor actively navigated the external pathology, slides, and wax-block workflow rather than treating family memory as sufficient.",
          "quote": "纸质报告和切片"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor recognized that original outside pathology, pathology consultation, admission/surgical planning, and later postoperative records could use different wording. They actively built a plan around obtaining/confirming source reports and explaining differences without weakening timely evaluation.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_01347",
          "explanation": "The doctor prevented a false-negative error by stating cervical screening cannot exclude endometrial cancer.",
          "quote": "不能用来排除子宫内膜癌"
        },
        {
          "event_id": "lite_evt_01480",
          "explanation": "The doctor prevented false-positive overdiagnosis of metastasis/ascites from nonspecific CT findings.",
          "quote": "完全不支持“已经淋巴转移了”"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor explicitly avoided both directions of error: not using a negative cervical screen to dismiss endometrial risk and not declaring metastasis, staging, or adjuvant therapy before pathology/imaging supported it.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00218",
          "explanation": "The doctor reprioritized pathology/material acquisition and MRI as parallel workstreams rather than sequential delay.",
          "quote": "两个可以并行"
        },
        {
          "event_id": "lite_evt_01458",
          "explanation": "When a staging CT gap emerged, the doctor changed priority to immediate same-day confirmation and correction.",
          "quote": "CT就不会漏"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor dynamically reordered tasks when barriers emerged: pathology and MRI were kept parallel, CT order failure prompted immediate repair, and symptom changes were repeatedly linked to urgent escalation rather than routine waiting.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
